Tb={'1':np.ones_like(T),'T':T,'T2':T**2,'T3':T**3,'1/T':1/T,'sqrtT':np.sqrt(T),'cosT':np.cos(T),'sinT':np.sin(T),'logT':np.log(T),'1/sqrtT':1/np.sqrt(T)}
