E0=lambda k: eps*np.exp(-k*eps)/T
res=[]
ks=np.linspace(0.750,0.762,13)
for m in range(3,7):
    for sub in itertools.combinations(names,m):
        if 'sinT' not in sub and 'cosT' not in sub: continue
        bestv=None
        for k in ks:
            A=np.column_stack([Tb[n] for n in sub]+[E0(k)])
            c=np.linalg.lstsq(A,sigma,rcond=None)[0]
            r=sigma-A@c
            v=np.mean(r**2)/np.var(sigma)
            if bestv is None or v<bestv[0]: bestv=(v,k,c)
        res.append((bestv[0],sub,round(bestv[1],5),np.round(bestv[2],5)))
